	protected static void assertUndefined(CodeUnit cu) {
		if (cu is Data data && DataType.DEFAULT.equals(data.getDataType()) &&
			!data.isDefined()) {
			return;
		}
		fail("Expected undefined unit, but was '%s'".formatted(cu));
	}

	protected List<T> takeN<T>(int n, Iterator<T> it) {
		List<T> result = new(n);
		for (int i = 0; i < n && it.hasNext(); i++) {
			result.add(it.next());
		}
		return result;
	}

